format.typst_code:
#set page(
  paper: "a5",
  flipped: true,
  margin: 0mm,
  background: [
    #place(top + left, dx: 5mm, dy: 5mm)[Company Logo],
    #place(top + right, dx: -5mm, dy: 5mm)[Company address and contacts]
  ]
)

#let sunderline = (thickness: 0.25mm, dash: (0.1mm, 0.5mm), cap: "round", join: "round")

// Payment Type
#if doc.payment_type == "Receive" {
  place(top + center, dx: 0mm, dy: 10mm)[
    #text(lang: "ar", "ســــــــــنــــــــــد قـــــبــــــــــض", font: "Muna", size: 19pt, weight: 600)
  ]
  place(top + center, dx: 0mm, dy: 18.5mm)[
    #text("Receipt Voucher", font: "Rajdhani", size: 14pt, weight: 700)
  ]
} else {
  place(top + center, dx: 0mm, dy: 10mm)[
    #text(lang: "ar", "ســــــــــنــــــــــد صـــــرف", font: "Muna", size: 19pt, weight: 600)
  ]
  place(top + center, dx: 0mm, dy: 18.5mm)[
    #text("Payment Voucher", font: "Rajdhani", size: 14pt, weight: 700)
  ]
}

// Layout frame
#place(top + left, dx: 5mm, dy: 47.5mm)[
  #rect(radius: 8mm, width: 200mm, height: 95.5mm, stroke: 0.25pt)
]
#place(top + left, dx: 13mm, dy: 41.5mm)[
  #rect(radius: 2mm, width: 42mm, height: 12mm, stroke: 1pt, fill: rgb("#f1f2f2"))
]
#place(top + right, dx: -12mm, dy: 41.5mm)[
  #rect(radius: 2mm, width: 58mm, height: 12mm, stroke: 1pt, fill: rgb("#f1f2f2"))
]
#place(top + left, dx: 15mm, dy: 38.4mm)[
  #text("Kuwaiti Dinar", font: "Rajdhani", size: 8pt, weight: 700)
]
#place(top + left, dx: 41mm, dy: 38.3mm)[
  #text(lang: "ar", "دينار كويتي", font: "Muna", size: 8pt, weight: 900)
]

// Voucher number
#place(top + right, dx: -8mm, dy: 41.5mm)[
  #rect(width: 65mm, height: 12mm, stroke: 0pt)[
    #text(font: "Oswald", size: 18pt, red, weight: 500)[#align(horizon + center)[#doc.name]]
  ]
]

#let amount = if "received_amount" in doc { str(doc.received_amount).replace("KWD ", "") } else { "" }
#place(top + left, dx: 13mm, dy: 42mm)[
  #rect(width: 42mm, height: 11mm, stroke: 0pt)[
    #text(font: "STIX Two Text", size: 18pt, weight: 700, red)[#align(horizon + right)[#amount]]
  ]
]

#place(top + right, dx: -7mm, dy: 58mm)[#text(lang: "ar", "التاريخ", font: "Muna", size: 14pt)]
#place(top + left, dx: 154mm, dy: 59mm)[#text("Date", font: "Eurostile", size: 10pt)]
#place(top + left, dx: 163mm, dy: 56.6mm)[
  #rect(width: 28mm, height: 7mm, stroke: (bottom: sunderline))[
    #align(center)[#text(font: "Inter", size: 14pt, fill: rgb("#0000cc"))[#doc.posting_date]]
  ]
]

#place(top + right, dx: -7mm, dy: 68mm)[#text(lang: "ar", "وصلنا من السادة", font: "Muna", size: 14pt)]
#place(top + left, dx: 7mm, dy: 69mm)[#text("Received from M/S", font: "Eurostile", size: 10pt)]
#place(top + left, dx: 38mm, dy: 66.7mm)[
  #rect(width: 138mm, height: 7mm, stroke: (bottom: sunderline))[
    #text(font: "Inter", size: 14pt, weight: 600, fill: rgb("#0000cc"))[#doc.party_name]
  ]
]

#place(top + right, dx: -7mm, dy: 78mm)[#text(lang: "ar", "مبلغ و قدره د.ك.", font: "Muna", size: 14pt)]
#place(top + left, dx: 7mm, dy: 79mm)[#text("The Sum of", font: "Eurostile", size: 10pt)]
#place(top + left, dx: 30mm, dy: 76.7mm)[
  #rect(width: 141mm, height: 7mm, stroke: (bottom: sunderline))[
    #text(font: "Inter", size: 10pt, weight: 600, fill: rgb("#0000cc"))[#doc.in_words]
  ]
]

#place(top + right, dx: -7mm, dy: 88mm)[#text(lang: "ar", "طريقة الدفع", font: "Muna", size: 14pt)]
#place(top + left, dx: 128mm, dy: 89mm)[#text("Method", font: "Eurostile", size: 10pt)]
#place(top + left, dx: 141mm, dy: 86.7mm)[
  #rect(width: 41mm, height: 7mm, stroke: (bottom: sunderline))[
    #align(center)[#text(font: "Inter", size: 14pt, weight: 600, fill: rgb("#0000cc"))[#doc.mode_of_payment]]
  ]
]

#place(top + right, dx: -84mm, dy: 88mm)[#text(lang: "ar", "شيك رقم", font: "Muna", size: 14pt)]
#place(top + left, dx: 67mm, dy: 89mm)[#text("Cheque No.", font: "Eurostile", size: 10pt)]
#place(top + left, dx: 85mm, dy: 86.7mm)[
  #rect(width: 25mm, height: 7mm, stroke: (bottom: sunderline))[]
]

#place(top + right, dx: -145mm, dy: 88mm)[#text(lang: "ar", "بنك", font: "Muna", size: 14pt)]
#place(top + left, dx: 7mm, dy: 89mm)[#text("Bank", font: "Eurostile", size: 10pt)]
#place(top + left, dx: 16mm, dy: 86.7mm)[
  #rect(width: 41mm, height: 7mm, stroke: (bottom: sunderline))[
    #align(center)[#text(lang: "ar", font: "Almohanad long kaf", size: 14pt, weight: "black", fill: rgb("#0000cc"))[#doc.bank]]
  ]
]

#place(top + right, dx: -7mm, dy: 98mm)[#text(lang: "ar", "و ذلك عن", font: "Muna", size: 14pt)]
#place(top + left, dx: 7mm, dy: 99mm)[#text("For", font: "Eurostile", size: 10pt)]
#place(top + left, dx: 14mm, dy: 103.7mm)[#line(start: (0mm, 0mm), length: 172mm, stroke: sunderline)]
#place(top + left, dx: 14mm, dy: 110.7mm)[#line(start: (0mm, 0mm), length: 172mm, stroke: sunderline)]
#place(top + left, dx: 14mm, dy: 117.7mm)[#line(start: (0mm, 0mm), length: 172mm, stroke: sunderline)]
#place(top + left, dx: 14mm, dy: 96.7mm)[
  #rect(width: 172mm, height: 7mm, stroke: 0pt)[
    #text(font: "Inter", size: 14pt, fill: rgb("#0000cc"))[#doc.remarks]
  ]
]
